sp_widget.client_script:
api.controller = function($scope, $window, snAttachmentHandler) {


    var c = this;


    /* ======================================================
       GENERAL STATE
    ====================================================== */

    c.step = 1;

    c.submitting = false;

    c.errorMessage = '';

    c.createdNumber = '';

    c.createdSysId = '';

    c.selectedImage = null;

    c.selectedImageSize = '';

    c.selectedImagePreview = '';

    c.photoChoice = '';

    c.locationSelected = false;


    /* ======================================================
       FORM
    ====================================================== */

    c.form = {

        title: '',

        category: '',

        description: '',

        date: '',

        time: '',

        locationX: '',

        locationY: '',

        locationZone: '',

        brand: '',

        color: '',

        uniqueFeatures: '',

        privateDetail1: '',

        privateDetail2: '',

        privateDetail3: ''

    };


    /* ======================================================
       DATE / TIME
       EXACT LOCAL VALUES + FUTURE RESTRICTION
    ====================================================== */

    function pad2(value) {

        return value < 10
            ? '0' + value
            : value.toString();

    }


    /* ======================================================
       GET EXACT LOCAL DATE
       RETURNS YYYY-MM-DD
    ====================================================== */

    function getExactDate(value) {

        if (!value) {

            return '';

        }


        /*
         * Angular date input may store a Date object.
         *
         * Use LOCAL values.
         * Do NOT use UTC / toISOString().
         */

        if (
            Object.prototype
                .toString
                .call(value) === '[object Date]' &&
            !isNaN(
                value.getTime()
            )
        ) {

            return (
                value.getFullYear() +
                '-' +
                pad2(
                    value.getMonth() + 1
                ) +
                '-' +
                pad2(
                    value.getDate()
                )
            );

        }


        var raw =
            value
                .toString()
                .trim();


        /*
         * Already correct format.
         */

        if (
            /^\d{4}-\d{2}-\d{2}$/
                .test(
                    raw
                )
        ) {

            return raw;

        }


        var parsed =
            new Date(
                raw
            );


        if (
            !isNaN(
                parsed.getTime()
            )
        ) {

            return (
                parsed.getFullYear() +
                '-' +
                pad2(
                    parsed.getMonth() + 1
                ) +
                '-' +
                pad2(
                    parsed.getDate()
                )
            );

        }


        return '';

    }


    /* ======================================================
       GET EXACT LOCAL TIME
       RETURNS HH:mm
    ====================================================== */

    function getExactTime(value) {

        if (!value) {

            return '';

        }


        /*
         * Angular time input may also store
         * a Date object.
         */

        if (
            Object.prototype
                .toString
                .call(value) === '[object Date]' &&
            !isNaN(
                value.getTime()
            )
        ) {

            return (
                pad2(
                    value.getHours()
                ) +
                ':' +
                pad2(
                    value.getMinutes()
                )
            );

        }


        var raw =
            value
                .toString()
                .trim();


        /*
         * HH:mm / HH:mm:ss
         */

        var direct =
            raw.match(
                /^(\d{2}):(\d{2})/
            );


        if (direct) {

            return (
                direct[1] +
                ':' +
                direct[2]
            );

        }


        var parsed =
            new Date(
                raw
            );


        if (
            !isNaN(
                parsed.getTime()
            )
        ) {

            return (
                pad2(
                    parsed.getHours()
                ) +
                ':' +
                pad2(
                    parsed.getMinutes()
                )
            );

        }


        return '';

    }


    /* ======================================================
       CURRENT DATE / TIME
    ====================================================== */

    c.todayDate = '';

    c.currentTime = '';


    c.refreshDateTimeLimits =
        function() {

            var now =
                new Date();


            c.todayDate =
                getExactDate(
                    now
                );


            c.currentTime =
                getExactTime(
                    now
                );

        };


    /*
     * When a past date is selected,
     * any time is allowed.
     *
     * When today is selected,
     * max time = current time.
     */

    c.getMaxTimeForSelectedDate =
        function() {

            var selectedDate =
                getExactDate(
                    c.form.date
                );


            if (
                selectedDate ===
                    c.todayDate
            ) {

                return c.currentTime;

            }


            return '';

        };


    /* ======================================================
       DATE CHANGED
    ====================================================== */

    c.onReportedDateChange =
        function() {

            c.refreshDateTimeLimits();


            var selectedDate =
                getExactDate(
                    c.form.date
                );


            var selectedTime =
                getExactTime(
                    c.form.time
                );


            /*
             * Example:
             *
             * User selected 11 PM yesterday,
             * then changes date to today at 3 PM.
             *
             * 11 PM becomes invalid, so remove it.
             */

            if (
                selectedDate ===
                    c.todayDate &&
                selectedTime &&
                selectedTime >
                    c.currentTime
            ) {

                c.form.time =
                    null;


                var timeInput =
                    $window.document
                        .getElementById(
                            'campusmatchReportedTime'
                        );


                if (timeInput) {

                    timeInput.value =
                        '';

                }


                c.errorMessage =
                    'Future time is not allowed for today.';

            }

        };


    /* ======================================================
       TIME CHANGED
       BLOCK FUTURE TIME WHEN DATE = TODAY
    ====================================================== */

    c.onReportedTimeChange =
        function() {

            c.refreshDateTimeLimits();


            var selectedDate =
                getExactDate(
                    c.form.date
                );


            var selectedTime =
                getExactTime(
                    c.form.time
                );


            /*
             * Past dates may use any time.
             *
             * Today may only use current time
             * or an earlier time.
             */

            if (
                selectedDate ===
                    c.todayDate &&
                selectedTime &&
                selectedTime >
                    c.currentTime
            ) {

                c.form.time =
                    null;


                var timeInput =
                    $window.document
                        .getElementById(
                            'campusmatchReportedTime'
                        );


                if (timeInput) {

                    timeInput.value =
                        '';

                }


                c.errorMessage =
                    'Future time is not allowed for today.';


                return;

            }


            /*
             * Clear only this specific error
             * after a valid time is entered.
             */

            if (
                c.errorMessage ===
                    'Future time is not allowed for today.'
            ) {

                c.errorMessage =
                    '';

            }

        };


    /* ======================================================
       VALIDATE DATE / TIME
    ====================================================== */

    c.validateReportedDateTime =
        function() {

            c.refreshDateTimeLimits();


            var selectedDate =
                getExactDate(
                    c.form.date
                );


            var selectedTime =
                getExactTime(
                    c.form.time
                );


            /* ----------------------------------------------
               DATE REQUIRED
            ---------------------------------------------- */

            if (!selectedDate) {

                c.errorMessage =
                    c.reportType === 'found'
                        ? 'Please select the date the item was found.'
                        : 'Please select the date the item was lost.';


                return false;

            }


            /* ----------------------------------------------
               TIME REQUIRED
            ---------------------------------------------- */

            if (!selectedTime) {

                c.errorMessage =
                    'Please select the approximate time.';


                return false;

            }


            /* ----------------------------------------------
               FUTURE DATE
            ---------------------------------------------- */

            if (
                selectedDate >
                    c.todayDate
            ) {

                c.errorMessage =
                    'Future dates are not allowed.';


                return false;

            }


            /* ----------------------------------------------
               TODAY + FUTURE TIME
            ---------------------------------------------- */

            if (
                selectedDate ===
                    c.todayDate &&
                selectedTime &&
                selectedTime >
                    c.currentTime
            ) {

                c.errorMessage =
                    'Future time is not allowed for today.';


                return false;

            }


            return true;

        };


    /* ======================================================
       REVIEW DISPLAY VALUES
    ====================================================== */

    c.getDisplayDate =
        function() {

            return (
                getExactDate(
                    c.form.date
                ) ||
                '—'
            );

        };


    c.getDisplayTime =
        function() {

            return (
                getExactTime(
                    c.form.time
                ) ||
                '—'
            );

        };


    /*
     * Initial date/time limits.
     */

    c.refreshDateTimeLimits();


    /* ======================================================
       REPORT TYPE FROM URL
    ====================================================== */

    var params =
        new URLSearchParams(
            $window.location.search
        );


    var type =
        params.get(
            'type'
        );


    if (
        type === 'found'
    ) {

        c.reportType =
            'found';

    }
    else {

        c.reportType =
            'lost';

    }


    /* ======================================================
       LOCATION PICKER EVENT
    ====================================================== */

    var locationListener =
        $scope.$on(

            'campusmatch.location.selected',

            function(
                event,
                location
            ) {

                $scope.$evalAsync(
                    function() {

                        c.form.locationX =
                            location.x;


                        c.form.locationY =
                            location.y;


                        c.form.locationZone =
                            location.zone;


                        c.locationSelected =
                            true;

                    }
                );

            }

        );


    /* ======================================================
       LOCATION CLEARED EVENT
    ====================================================== */

    var locationClearListener =
        $scope.$on(

            'campusmatch.location.cleared',

            function() {

                $scope.$evalAsync(
                    function() {

                        c.form.locationX =
                            '';


                        c.form.locationY =
                            '';


                        c.form.locationZone =
                            '';


                        c.locationSelected =
                            false;

                    }
                );

            }

        );


    /* ======================================================
       DESTROY LISTENERS
    ====================================================== */

    $scope.$on(

        '$destroy',

        function() {

            locationListener();

            locationClearListener();

        }

    );


    /* ======================================================
       LOST / FOUND SWITCH
    ====================================================== */

    c.setType =
        function(type) {

            c.reportType =
                type;


            c.step =
                1;


            c.errorMessage =
                '';

        };


    /* ======================================================
       VALIDATE CURRENT STEP
    ====================================================== */

    c.validateCurrentStep =
        function() {

            c.errorMessage =
                '';


            /* ==============================================
               STEP 1
            ============================================== */

            if (
                c.step === 1
            ) {

                if (
                    !c.form.title ||
                    !c.form.title.trim()
                ) {

                    c.errorMessage =
                        'Please enter an item title.';


                    return false;

                }


                if (
                    !c.form.category
                ) {

                    c.errorMessage =
                        'Please select a category.';


                    return false;

                }


                /*
                 * DATE / TIME VALIDATION
                 */

                if (
                    !c.validateReportedDateTime()
                ) {

                    return false;

                }

            }


            /* ==============================================
               STEP 3 — PHOTO
            ============================================== */

            if (
                c.step === 3
            ) {

                if (
                    !c.photoChoice
                ) {

                    c.errorMessage =
                        'Please tell us whether you have a photo of the item.';


                    return false;

                }


                if (
                    c.photoChoice ===
                        'yes' &&
                    !c.selectedImage
                ) {

                    c.errorMessage =
                        'Please choose a photo before continuing.';


                    return false;

                }


                if (
                    c.photoChoice ===
                        'no'
                ) {

                    if (
                        !c.form.color ||
                        !c.form.color.trim()
                    ) {

                        c.errorMessage =
                            'Please enter the item color.';


                        return false;

                    }


                    if (
                        !c.form.uniqueFeatures ||
                        !c.form.uniqueFeatures
                            .trim()
                    ) {

                        c.errorMessage =
                            'Please describe at least one unique feature of the item.';


                        return false;

                    }

                }

            }


            /* ==============================================
               FOUND PRIVATE DETAILS
            ============================================== */

            if (
                c.reportType ===
                    'found' &&
                c.step === 4
            ) {

                if (
                    !c.form.privateDetail1 ||
                    !c.form.privateDetail1
                        .trim() ||
                    !c.form.privateDetail2 ||
                    !c.form.privateDetail2
                        .trim()
                ) {

                    c.errorMessage =
                        'Please provide at least two private verification details.';


                    return false;

                }

            }


            return true;

        };


    /* ======================================================
       NEXT STEP
    ====================================================== */

    c.next =
        function() {

            if (
                !c.validateCurrentStep()
            ) {

                return;

            }


            c.errorMessage =
                '';


            c.step +=
                1;


            $window.scrollTo(
                0,
                0
            );

        };


    /* ======================================================
       PREVIOUS STEP
    ====================================================== */

    c.previous =
        function() {

            c.errorMessage =
                '';


            if (
                c.step > 1
            ) {

                c.step -=
                    1;

            }


            $window.scrollTo(
                0,
                0
            );

        };


    /* ======================================================
       PHOTO OPTION
    ====================================================== */

    c.choosePhotoOption =
        function(choice) {

            c.errorMessage =
                '';


            c.photoChoice =
                choice;


            /*
             * YES:
             * clear old manually entered visual details.
             */

            if (
                choice === 'yes'
            ) {

                c.form.brand =
                    '';

                c.form.color =
                    '';

                c.form.uniqueFeatures =
                    '';

            }


            /*
             * NO:
             * remove previously selected image.
             */

            if (
                choice === 'no'
            ) {

                c.removeImage();

                c.photoChoice =
                    'no';

            }

        };


    /* ======================================================
       SELECT IMAGE
    ====================================================== */

    c.selectImage =
        function(files) {

            c.errorMessage =
                '';


            if (
                !files ||
                !files.length
            ) {

                return;

            }


            var file =
                files[0];


            var allowedTypes = [

                'image/jpeg',

                'image/png'

            ];


            if (
                allowedTypes.indexOf(
                    file.type
                ) === -1
            ) {

                c.selectedImage =
                    null;


                c.selectedImageSize =
                    '';


                c.selectedImagePreview =
                    '';


                c.errorMessage =
                    'Please upload a JPG or PNG image.';


                return;

            }


            var maxSize =
                5 *
                1024 *
                1024;


            if (
                file.size >
                    maxSize
            ) {

                c.selectedImage =
                    null;


                c.selectedImageSize =
                    '';


                c.selectedImagePreview =
                    '';


                c.errorMessage =
                    'Image must be smaller than 5 MB.';


                return;

            }


            c.selectedImage =
                file;


            c.selectedImageSize =
                (
                    file.size /
                    (
                        1024 *
                        1024
                    )
                )
                .toFixed(
                    2
                ) +
                ' MB';


            /* ==============================================
               IMAGE PREVIEW
            ============================================== */

            var reader =
                new FileReader();


            reader.onload =
                function(event) {

                    $scope.$evalAsync(
                        function() {

                            c.selectedImagePreview =
                                event.target.result;

                        }
                    );

                };


            reader.readAsDataURL(
                file
            );

        };


    /* ======================================================
       REMOVE IMAGE
    ====================================================== */

    c.removeImage =
        function() {

            c.selectedImage =
                null;


            c.selectedImageSize =
                '';


            c.selectedImagePreview =
                '';


            c.errorMessage =
                '';


            var input =
                document.getElementById(
                    'campusmatchImage'
                );


            if (input) {

                input.value =
                    '';

            }

        };


    /* ======================================================
       CATEGORY LABEL
    ====================================================== */

    c.getCategoryLabel =
        function() {

            var labels = {

                electronics:
                    'Electronics',

                bags:
                    'Bags',

                books:
                    'Books',

                clothing:
                    'Clothing',

                accessories:
                    'Accessories',

                id_cards:
                    'ID / Cards',

                keys:
                    'Keys',

                documents:
                    'Documents',

                other:
                    'Other'

            };


            return (
                labels[
                    c.form.category
                ] ||
                '—'
            );

        };


    /* ======================================================
       RUN MATCHING
    ====================================================== */

    c.runMatching =
        function(itemSysId) {

            c.server.get({

                action:
                    'runMatching',

                item_sys_id:
                    itemSysId

            }).then(

                function(response) {

                    if (
                        !response ||
                        !response.data ||
                        !response.data.success
                    ) {

                        console.log(
                            'CampusMatch matching warning:',
                            response &&
                            response.data
                                ?
                                response.data.message
                                :
                                'Matching request failed.'
                        );

                    }


                    c.finishSubmission();

                },

                function(error) {

                    console.log(
                        'CampusMatch matching request failed:',
                        error
                    );


                    c.finishSubmission();

                }

            );

        };


    /* ======================================================
       GET ATTACHMENT SYS ID
    ====================================================== */

    c.getAttachmentSysId =
        function(response) {

            if (
                !response
            ) {

                return '';

            }


            if (
                response.sys_id
            ) {

                return response.sys_id;

            }


            if (
                response.data &&
                response.data.sys_id
            ) {

                return response.data.sys_id;

            }


            if (
                response.result &&
                response.result.sys_id
            ) {

                return response.result.sys_id;

            }


            if (
                response.data &&
                response.data.result &&
                response.data.result.sys_id
            ) {

                return response
                    .data
                    .result
                    .sys_id;

            }


            if (
                response.length &&
                response[0] &&
                response[0].sys_id
            ) {

                return response[0]
                    .sys_id;

            }


            return '';

        };


    /* ======================================================
       CONVERT IMAGE
    ====================================================== */

    c.convertUploadedImage =
        function(
            itemSysId,
            attachmentSysId
        ) {

            var fileName =
                (
                    c.selectedImage &&
                    c.selectedImage.name
                )
                    ?
                    c.selectedImage.name
                    :
                    '';


            c.server.get({

                action:
                    'convertImageAttachment',

                item_sys_id:
                    itemSysId,

                attachment_sys_id:
                    attachmentSysId ||
                    '',

                file_name:
                    fileName

            }).then(

                function(
                    convertResponse
                ) {

                    if (
                        !convertResponse ||
                        !convertResponse.data ||
                        !convertResponse
                            .data
                            .success
                    ) {

                        c.submitting =
                            false;


                        c.errorMessage =
                            (
                                convertResponse &&
                                convertResponse.data &&
                                convertResponse
                                    .data
                                    .message
                            )
                                ?
                                convertResponse
                                    .data
                                    .message
                                :
                                'The report was created, but the image could not be processed.';


                        return;

                    }


                    c.finishSubmission();

                },

                function() {

                    c.submitting =
                        false;


                    c.errorMessage =
                        'The report was created, but the image could not be processed.';

                }

            );

        };


    /* ======================================================
       UPLOAD IMAGE
    ====================================================== */

    c.uploadImage =
        function(itemSysId) {

            if (
                !c.selectedImage
            ) {

                c.runMatching(
                    itemSysId
                );


                return;

            }


            var attachmentHandler =
                snAttachmentHandler
                    .create(

                        'x_snc_campusmatch_campusmatch_item',

                        itemSysId

                    );


            attachmentHandler
                .uploadAttachment(
                    c.selectedImage
                )
                .then(

                    function(response) {

                        var attachmentSysId =
                            c.getAttachmentSysId(
                                response
                            );


                        console.log(
                            'CampusMatch attachment upload response:',
                            response
                        );


                        console.log(
                            'CampusMatch attachment sys_id:',
                            attachmentSysId ||
                            '(not exposed - server fallback will locate it)'
                        );


                        c.convertUploadedImage(
                            itemSysId,
                            attachmentSysId
                        );

                    },

                    function(error) {

                        c.submitting =
                            false;


                        c.errorMessage =
                            'The report was created, but the photo upload failed.';


                        console.log(
                            'CampusMatch photo upload error:',
                            error
                        );

                    }

                );

        };


    /* ======================================================
       FINISH SUBMISSION
    ====================================================== */

    c.finishSubmission =
        function() {

            c.submitting =
                false;


            c.errorMessage =
                '';


            c.step =
                'success';


            $window.scrollTo(
                0,
                0
            );

        };


    /* ======================================================
       SUBMIT REPORT
    ====================================================== */

    c.submitReport =
        function() {

            c.errorMessage =
                '';


            if (
                c.submitting
            ) {

                return;

            }


            if (
                !c.form.title ||
                !c.form.title.trim()
            ) {

                c.errorMessage =
                    'Please enter a title.';


                return;

            }


            if (
                !c.form.category
            ) {

                c.errorMessage =
                    'Please select a category.';


                return;

            }


            /*
             * Revalidate immediately before submission.
             */

            if (
                !c.validateReportedDateTime()
            ) {

                return;

            }


            /* ==================================================
               LOCATION VALIDATION
            ================================================== */

            var missingX =
                c.form.locationX ===
                    '' ||
                c.form.locationX ===
                    null ||
                typeof c.form.locationX ===
                    'undefined';


            var missingY =
                c.form.locationY ===
                    '' ||
                c.form.locationY ===
                    null ||
                typeof c.form.locationY ===
                    'undefined';


            if (
                missingX ||
                missingY ||
                !c.form.locationZone
            ) {

                c.errorMessage =
                    'Please select the item location on the campus map.';


                return;

            }


            /* ==================================================
               PHOTO VALIDATION
            ================================================== */

            if (
                !c.photoChoice
            ) {

                c.errorMessage =
                    'Please tell us whether you have a photo of the item.';


                return;

            }


            if (
                c.photoChoice ===
                    'yes' &&
                !c.selectedImage
            ) {

                c.errorMessage =
                    'Please choose a photo before submitting.';


                return;

            }


            if (
                c.photoChoice ===
                    'no'
            ) {

                if (
                    !c.form.color ||
                    !c.form.color.trim()
                ) {

                    c.errorMessage =
                        'Please enter the item color.';


                    return;

                }


                if (
                    !c.form.uniqueFeatures ||
                    !c.form.uniqueFeatures
                        .trim()
                ) {

                    c.errorMessage =
                        'Please describe at least one unique feature of the item.';


                    return;

                }

            }


            /* ==================================================
               FOUND PRIVATE DETAILS VALIDATION
            ================================================== */

            if (
                c.reportType ===
                    'found'
            ) {

                if (
                    !c.form.privateDetail1 ||
                    !c.form.privateDetail1
                        .trim()
                ) {

                    c.errorMessage =
                        'Please enter Private Verification Detail 1.';


                    return;

                }


                if (
                    !c.form.privateDetail2 ||
                    !c.form.privateDetail2
                        .trim()
                ) {

                    c.errorMessage =
                        'Please enter Private Verification Detail 2.';


                    return;

                }

            }


            c.submitting =
                true;


            /* ==================================================
               CREATE REPORT
            ================================================== */

            c.server.get({

                action:
                    'createReport',

                report_type:
                    c.reportType,

                title:
                    c.form.title,

                category:
                    c.form.category,

                description:
                    c.form.description,


                /*
                 * IMPORTANT:
                 *
                 * Send exact local strings.
                 *
                 * Do NOT send the raw Angular Date object.
                 */

                reported_date:
                    getExactDate(
                        c.form.date
                    ),

                reported_time:
                    getExactTime(
                        c.form.time
                    ),


                location_x:
                    c.form.locationX,

                location_y:
                    c.form.locationY,

                location_zone:
                    c.form.locationZone,

                photo_mode:
                    c.photoChoice,

                brand:
                    c.form.brand,

                color:
                    c.form.color,

                unique_features:
                    c.form.uniqueFeatures,

                private_1:
                    c.form.privateDetail1,

                private_2:
                    c.form.privateDetail2,

                private_3:
                    c.form.privateDetail3

            }).then(

                function(response) {

                    if (
                        !response ||
                        !response.data ||
                        !response.data.success
                    ) {

                        c.submitting =
                            false;


                        c.errorMessage =
                            (
                                response &&
                                response.data &&
                                response.data.message
                            )
                                ?
                                response.data.message
                                :
                                'Unable to create report.';


                        return;

                    }


                    c.createdSysId =
                        response.data.sys_id;


                    c.createdNumber =
                        response.data.number;


                    if (
                        c.photoChoice ===
                            'yes' &&
                        c.selectedImage
                    ) {

                        c.uploadImage(
                            c.createdSysId
                        );

                    }
                    else {

                        c.runMatching(
                            c.createdSysId
                        );

                    }

                },

                function() {

                    c.submitting =
                        false;


                    c.errorMessage =
                        'Unable to create report. Please try again.';

                }

            );

        };

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH REPORT ITEM
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================== */

.cm-report-page {
  position: relative;
  display: block;

  /* FULL WIDTH OUTSIDE SERVICENOW WRAPPER */
  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding:
    56px
    20px
    90px;

  background:
    linear-gradient(
      180deg,
      #FBF8EF 0%,
      #F5F7F0 100%
    );

  /*
     Covers ServiceNow external top/bottom white spacing
     without moving this widget or touching Header.
  */
  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #F5F7F0;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  color: #102E34;

  box-sizing: border-box !important;

  overflow-x: hidden;
}


/* ==========================================================
   SAFE BOX SIZING
========================================================== */

.cm-report-page,
.cm-report-page *,
.cm-report-page *::before,
.cm-report-page *::after {
  box-sizing: border-box;
}


/* ==========================================================
   CONTAINER
========================================================== */

.cm-report-container {
  position: relative;

  width: 100%;

  max-width: 780px;

  margin: 0 auto;
}


/* ==========================================================
   HEADER
========================================================== */

.cm-report-header {
  text-align: center;

  margin-bottom: 28px;
}


.cm-report-eyebrow {
  display: inline-flex;

  align-items: center;

  padding:
    8px
    16px;

  margin-bottom: 16px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 13px;

  font-weight: 700;
}


.cm-report-header h1 {
  margin:
    0
    0
    10px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 38px;

  font-weight: 700;

  line-height: 1.12;

  letter-spacing: -1px;
}


.cm-report-header p {
  max-width: 520px;

  margin: 0 auto;

  color: #506267;

  font-size: 16px;

  line-height: 1.6;
}


/* ==========================================================
   LOST / FOUND SWITCH
========================================================== */

.cm-type-switch {
  width: fit-content;

  margin:
    0
    auto
    34px;

  padding: 5px;

  display: flex;

  gap: 5px;

  border-radius: 999px;

  background: #E7EFE8;
}


.cm-type-switch button {
  min-width: 135px;

  padding:
    11px
    20px;

  border: 0;

  border-radius: 999px;

  background: transparent;

  color: #15564B;

  font-family: inherit;

  font-weight: 700;

  cursor: pointer;

  transition:
    background .2s ease,
    color .2s ease,
    box-shadow .2s ease;
}


.cm-type-switch button.active {
  background: #104E45;

  color: #FFFFFF;

  box-shadow:
    0 7px 18px rgba(16,78,69,.14);
}


/* ==========================================================
   PROGRESS
========================================================== */

.cm-progress {
  width: 100%;

  display: flex;

  align-items: center;

  justify-content: center;

  margin-bottom: 32px;
}


.cm-progress-item {
  display: flex;

  align-items: center;

  gap: 7px;
}


.cm-progress-dot {
  width: 32px;

  height: 32px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  border: 1.5px solid #D2DED8;

  background: #FFFFFF;

  color: #77868A;

  font-size: 12px;

  font-weight: 700;
}


.cm-progress-label {
  color: #77868A;

  font-size: 12px;

  font-weight: 700;
}


.cm-progress-item.active .cm-progress-dot {
  background: #104E45;

  border-color: #104E45;

  color: #FFFFFF;
}


.cm-progress-item.active .cm-progress-label {
  color: #104E45;
}


.cm-progress-item.done .cm-progress-dot {
  background: #249D78;

  border-color: #249D78;

  color: #FFFFFF;
}


.cm-progress-line {
  width: 30px;

  height: 2px;

  margin:
    0
    8px;

  flex-shrink: 0;

  background: #D2DED8;
}


/* ==========================================================
   CARD
========================================================== */

.cm-report-card {
  width: 100%;

  padding: 38px;

  border: 1px solid #D2DED8;

  border-radius: 26px;

  background: #FFFFFF;

  box-shadow:
    0 14px 38px rgba(16,78,69,.08);
}


/* ==========================================================
   STEP HEADER
========================================================== */

.cm-step-heading {
  display: flex;

  align-items: flex-start;

  gap: 15px;

  margin-bottom: 30px;
}


.cm-step-number {
  width: 44px;

  height: 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 14px;

  background: #EDF5E9;

  color: #15564B;

  font-weight: 800;
}


.cm-step-heading h2 {
  margin:
    0
    0
    5px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 22px;

  font-weight: 700;
}


.cm-step-heading p {
  margin: 0;

  color: #687A7E;

  font-size: 14px;

  line-height: 1.5;
}


/* ==========================================================
   FIELDS
========================================================== */

.cm-field {
  margin-bottom: 22px;
}


.cm-field label {
  display: block;

  margin-bottom: 8px;

  color: #102E34;

  font-size: 14px;

  font-weight: 700;
}


.cm-field label > span {
  color: #B5502F;
}


.cm-field .cm-optional {
  margin-left: 6px;

  color: #77868A;

  font-size: 11px;

  font-weight: 500;
}


.cm-field input,
.cm-field select,
.cm-field textarea {
  width: 100%;

  max-width: 100%;

  padding:
    14px
    16px;

  border: 1.5px solid #D2DED8;

  border-radius: 15px;

  outline: none;

  background: #FFFFFF;

  color: #102E34;

  font-family: inherit;

  font-size: 14px;

  transition:
    border .2s ease,
    box-shadow .2s ease;
}


.cm-field textarea {
  min-height: 105px;

  resize: vertical;
}


.cm-field input:focus,
.cm-field select:focus,
.cm-field textarea:focus {
  border-color: #249D78;

  box-shadow:
    0 0 0 4px rgba(36,157,120,.10);
}


.cm-field-hint {
  margin-top: 6px;

  color: #7B898D;

  font-size: 12px;

  line-height: 1.5;
}


.cm-two-column {
  display: grid;

  grid-template-columns:
    minmax(0,1fr)
    minmax(0,1fr);

  gap: 16px;
}


/* ==========================================================
   MAP PLACEHOLDER
========================================================== */

.cm-map-placeholder {
  min-height: 310px;

  padding:
    38px
    20px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  margin-bottom: 20px;

  border: 2px dashed #BCD3C8;

  border-radius: 22px;

  background: #F3F8F0;

  text-align: center;
}


.cm-map-icon {
  width: 64px;

  height: 64px;

  display: flex;

  align-items: center;

  justify-content: center;

  margin-bottom: 12px;

  border-radius: 20px;

  background: #E1EFE5;

  color: #15564B;
}


.cm-map-icon svg {
  width: 34px;

  height: 34px;
}


.cm-map-placeholder h3 {
  margin:
    0
    0
    5px;

  color: #104E45;
}


.cm-map-placeholder p {
  margin:
    0
    0
    9px;

  color: #687A7E;

  font-size: 13px;
}


.cm-map-placeholder > span {
  padding:
    5px
    10px;

  border-radius: 999px;

  background: #FFFFFF;

  color: #249D78;

  font-size: 11px;

  font-weight: 700;
}


/* ==========================================================
   LOCATION
========================================================== */

.cm-map-wrapper {
  width: 100%;

  overflow: hidden;

  padding: 14px;

  margin-bottom: 15px;

  border: 1px solid #D2DED8;

  border-radius: 20px;

  background: #FFFFFF;

  box-shadow:
    0 5px 18px rgba(16,78,69,.05);
}


.cm-selected-location {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 18px;

  padding:
    15px
    17px;

  margin-bottom: 15px;

  border-radius: 15px;

  background: #EDF5E9;
}


.cm-selected-label {
  display: block;

  margin-bottom: 2px;

  color: #65777B;

  font-size: 11px;
}


.cm-selected-location strong {
  color: #104E45;

  word-break: break-word;
}


.cm-coordinate-text {
  flex-shrink: 0;

  color: #506267;

  font-size: 12px;
}


.cm-location-note {
  display: flex;

  align-items: center;

  gap: 9px;

  padding:
    13px
    15px;

  border-radius: 14px;

  background: #FAF3E4;

  color: #7D662D;

  font-size: 12px;

  line-height: 1.45;
}


.cm-location-note svg {
  width: 17px;

  height: 17px;

  flex-shrink: 0;
}


/* ==========================================================
   UPLOAD
========================================================== */

.cm-upload-zone {
  padding:
    45px
    25px;

  margin-bottom: 20px;

  border: 2px dashed #BCD3C8;

  border-radius: 22px;

  background: #F3F8F0;

  text-align: center;

  transition:
    border .2s ease,
    background .2s ease;
}


.cm-upload-zone:hover {
  border-color: #249D78;

  background: #EAF4EA;
}


.cm-upload-icon {
  width: 60px;

  height: 60px;

  margin:
    0
    auto
    13px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 19px;

  background: #E0EFE5;

  color: #15564B;
}


.cm-upload-icon svg {
  width: 31px;

  height: 31px;
}


.cm-upload-zone h3 {
  margin:
    0
    0
    4px;

  color: #104E45;

  font-size: 17px;
}


.cm-upload-zone p {
  margin:
    0
    0
    16px;

  color: #687A7E;

  font-size: 13px;
}


/* ==========================================================
   PHOTO UPLOAD BUTTON
========================================================== */

.cm-photo-upload-btn {
  display: inline-flex;

  align-items: center;

  justify-content: center;

  padding:
    11px
    18px;

  border: 1.5px solid #D2DED8;

  border-radius: 999px;

  background: #FFFFFF;

  color: #104E45;

  font-size: 11px;

  font-weight: 800;

  cursor: pointer;

  transition:
    border-color .2s ease,
    background .2s ease,
    transform .2s ease,
    box-shadow .2s ease;
}


.cm-photo-upload-btn:hover {
  border-color: #249D78;

  background: #FFFFFF;

  transform: translateY(-1px);

  box-shadow:
    0 5px 14px rgba(16,78,69,.08);
}


/* ==========================================================
   SELECTED PHOTO
========================================================== */

.cm-selected-photo {
  margin-top: -5px;

  margin-bottom: 20px;

  padding:
    12px
    14px;

  display: flex;

  align-items: center;

  gap: 10px;

  border-radius: 12px;

  background: #EDF5E9;
}


.cm-selected-photo strong {
  min-width: 0;

  flex: 1;

  overflow: hidden;

  color: #104E45;

  font-size: 11px;

  text-overflow: ellipsis;

  white-space: nowrap;
}


.cm-selected-photo span {
  flex-shrink: 0;

  color: #718185;

  font-size: 10px;
}


.cm-selected-photo button {
  flex-shrink: 0;

  padding:
    5px
    8px;

  border: 0;

  border-radius: 8px;

  background: transparent;

  color: #A44832;

  font-family: inherit;

  font-size: 10px;

  font-weight: 800;

  cursor: pointer;
}


.cm-selected-photo button:hover {
  background: #FBEAE7;
}


/* ==========================================================
   OLD CLASSES — SAFE TO KEEP
========================================================== */

.cm-file-name {
  color: #249D78 !important;

  font-weight: 700;
}


.cm-hidden-file {
  display: none;
}


/* ==========================================================
   AI NOTE
========================================================== */

.cm-ai-note {
  display: flex;

  align-items: flex-start;

  gap: 13px;

  padding: 15px;

  border-radius: 16px;

  background: #EDF5E9;
}


.cm-ai-badge {
  min-width: 40px;

  width: 40px;

  height: 40px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 13px;

  background: #15564B;

  color: #FFFFFF;

  font-size: 12px;

  font-weight: 800;
}


.cm-ai-note strong {
  display: block;

  margin-bottom: 3px;

  color: #104E45;

  font-size: 13px;
}


.cm-ai-note p {
  margin: 0;

  color: #687A7E;

  font-size: 12px;

  line-height: 1.5;
}


.cm-skip-note {
  margin-top: 12px;

  color: #77868A;

  text-align: center;

  font-size: 12px;
}


/* ==========================================================
   PRIVACY
========================================================== */

.cm-privacy-banner {
  display: flex;

  align-items: flex-start;

  gap: 12px;

  padding: 16px;

  margin-bottom: 25px;

  border-radius: 16px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-privacy-banner svg {
  width: 22px;

  height: 22px;

  flex-shrink: 0;
}


.cm-privacy-banner strong {
  display: block;

  margin-bottom: 2px;

  font-size: 13px;
}


.cm-privacy-banner p {
  margin: 0;

  color: #63777A;

  font-size: 12px;

  line-height: 1.5;
}


/* ==========================================================
   REVIEW
========================================================== */

.cm-review-row {
  display: grid;

  grid-template-columns:
    155px
    minmax(0,1fr);

  gap: 20px;

  padding:
    14px
    0;

  border-bottom: 1px solid #EDF2EE;
}


.cm-review-row > span {
  color: #758488;

  font-size: 13px;
}


.cm-review-row strong {
  min-width: 0;

  color: #102E34;

  font-size: 13px;

  font-weight: 700;

  word-break: break-word;
}


.cm-private-review {
  padding: 17px;

  margin-top: 22px;

  border-radius: 18px;

  background: #F4F8F2;
}


.cm-private-review-title {
  display: flex;

  align-items: center;

  gap: 8px;

  padding-bottom: 9px;

  color: #15564B;

  font-size: 13px;

  font-weight: 800;
}


.cm-private-review-title svg {
  width: 18px;

  height: 18px;

  flex-shrink: 0;
}


/* ==========================================================
   BUTTONS
========================================================== */

.cm-form-actions {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 14px;

  margin-top: 32px;
}


.cm-form-actions.cm-right {
  justify-content: flex-end;
}


.cm-btn {
  min-height: 48px;

  padding:
    12px
    22px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 8px;

  border: none;

  border-radius: 999px;

  font-family: inherit;

  font-size: 14px;

  font-weight: 700;

  text-decoration: none !important;

  cursor: pointer;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    background .2s ease;
}


.cm-btn-primary {
  background: #104E45;

  color: #FFFFFF !important;

  box-shadow:
    0 7px 18px rgba(16,78,69,.14);
}


.cm-btn-primary:hover {
  transform: translateY(-1px);

  background: #15564B;
}


.cm-btn-primary:disabled {
  opacity: .55;

  cursor: not-allowed;

  transform: none;
}


.cm-btn-secondary {
  border: 1.5px solid #D2DED8;

  background: #FFFFFF;

  color: #104E45 !important;
}


/* ==========================================================
   ERROR
========================================================== */

.cm-error {
  padding:
    13px
    15px;

  margin-top: 20px;

  border-radius: 13px;

  background: #FBEAE7;

  color: #A2432E;

  font-size: 13px;

  font-weight: 600;
}


.cm-form-error {
  margin-bottom: 14px;

  padding:
    11px
    14px;

  border-radius: 12px;

  background: #FBEAE7;

  color: #A44832;

  font-size: 11px;

  font-weight: 700;
}


/* ==========================================================
   SUCCESS
========================================================== */

.cm-success {
  padding:
    30px
    5px;

  text-align: center;
}


.cm-success-icon {
  width: 76px;

  height: 76px;

  margin:
    0
    auto
    19px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  background: #EDF5E9;

  color: #15564B;
}


.cm-success-icon svg {
  width: 34px;

  height: 34px;
}


.cm-success-eyebrow {
  display: inline-block;

  margin-bottom: 8px;

  color: #249D78;

  font-size: 12px;

  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: .8px;
}


.cm-success h2 {
  margin:
    0
    0
    11px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 28px;
}


.cm-success > p {
  max-width: 500px;

  margin: 0 auto;

  color: #617477;

  line-height: 1.65;
}


.cm-report-number {
  width: fit-content;

  margin:
    23px
    auto;

  padding:
    10px
    17px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #627477;

  font-size: 13px;
}


.cm-report-number strong {
  margin-left: 5px;

  color: #104E45;
}


.cm-dashboard-btn {
  margin-top: 25px;
}


/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 760px) {

  .cm-report-page {
    padding:
      40px
      18px
      70px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F5F7F0;
  }


  .cm-report-card {
    padding: 30px;
  }


  .cm-progress-label {
    display: none;
  }


  .cm-progress-line {
    width: 35px;

    margin:
      0
      5px;
  }

}


/* ==========================================================
   MOBILE
   WEBSITE MOBILE + NOW MOBILE APP
========================================================== */

@media (max-width: 560px) {

  .cm-report-page {
    min-height: 100svh;

    padding:
      30px
      14px
      60px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F5F7F0;
  }


  .cm-report-header {
    margin-bottom: 24px;
  }


  .cm-report-header h1 {
    font-size: 30px;

    line-height: 1.12;
  }


  .cm-report-header p {
    font-size: 14px;
  }


  .cm-report-eyebrow {
    font-size: 12px;

    padding:
      7px
      13px;
  }


  .cm-type-switch {
    width: 100%;

    max-width: 100%;
  }


  .cm-type-switch button {
    min-width: 0;

    flex: 1;

    padding:
      11px
      8px;

    font-size: 13px;
  }


  .cm-progress {
    overflow: hidden;
  }


  .cm-progress-dot {
    width: 29px;

    height: 29px;

    font-size: 11px;
  }


  .cm-progress-line {
    width: 22px;

    margin:
      0
      4px;
  }


  .cm-report-card {
    padding:
      23px
      19px;

    border-radius: 22px;
  }


  .cm-two-column {
    grid-template-columns: 1fr;

    gap: 0;
  }


  .cm-step-heading {
    gap: 11px;
  }


  .cm-step-number {
    width: 39px;

    height: 39px;

    font-size: 12px;
  }


  .cm-step-heading h2 {
    font-size: 19px;
  }


  .cm-step-heading p {
    font-size: 12px;
  }


  .cm-field input,
  .cm-field select,
  .cm-field textarea {
    font-size: 14px;
  }


  .cm-map-placeholder {
    min-height: 255px;
  }


  .cm-map-wrapper {
    padding: 10px;

    border-radius: 17px;
  }


  .cm-selected-location {
    align-items: flex-start;

    flex-direction: column;

    gap: 7px;
  }


  .cm-coordinate-text {
    flex-shrink: 1;
  }


  .cm-upload-zone {
    padding:
      35px
      18px;
  }


  .cm-selected-photo {
    align-items: flex-start;

    flex-wrap: wrap;
  }


  .cm-selected-photo strong {
    width: 100%;

    flex-basis: 100%;
  }


  .cm-selected-photo span {
    flex: 1;
  }


  .cm-review-row {
    grid-template-columns:
      115px
      minmax(0,1fr);

    gap: 12px;
  }


  .cm-form-actions {
    gap: 10px;
  }


  .cm-form-actions .cm-btn {
    flex: 1;

    padding:
      11px
      13px;

    font-size: 13px;
  }

}


/* ==========================================================
   SMALL PHONE
========================================================== */

@media (max-width: 380px) {

  .cm-report-page {
    padding:
      26px
      12px
      55px;
  }


  .cm-report-header h1 {
    font-size: 27px;
  }


  .cm-report-card {
    padding:
      20px
      16px;
  }


  .cm-progress-line {
    width: 15px;

    margin:
      0
      3px;
  }


  .cm-progress-dot {
    width: 27px;

    height: 27px;
  }


  .cm-review-row {
    grid-template-columns:
      95px
      minmax(0,1fr);
  }


  .cm-selected-photo {
    padding:
      11px
      12px;
  }


  .cm-form-actions .cm-btn {
    padding:
      10px
      9px;

    font-size: 12px;
  }

}


/* ==========================================================
   PHOTO AVAILABILITY CHOICE
========================================================== */

.cm-photo-choice {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 14px;

  margin-bottom: 25px;
}


.cm-photo-choice button {
  min-height: 135px;

  padding: 20px;

  display: flex;

  flex-direction: column;

  align-items: flex-start;

  justify-content: center;

  gap: 6px;

  border: 1.5px solid #D2DED8;

  border-radius: 18px;

  background: #FFFFFF;

  color: #102E34;

  font-family: inherit;

  text-align: left;

  cursor: pointer;

  transition:
    border-color .2s ease,
    background .2s ease,
    transform .2s ease,
    box-shadow .2s ease;
}


.cm-photo-choice button:hover {
  transform: translateY(-2px);

  border-color: #249D78;

  box-shadow:
    0 7px 18px rgba(16,78,69,.08);
}


.cm-photo-choice button.active {
  border-color: #168C70;

  background: #EDF5E9;

  box-shadow:
    0 0 0 3px rgba(36,157,120,.09);
}


.cm-photo-choice-icon {
  width: 38px;

  height: 38px;

  margin-bottom: 4px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-photo-choice button.active
.cm-photo-choice-icon {
  background: #FFFFFF;

  color: #168C70;
}


.cm-photo-choice-icon svg {
  width: 20px;

  height: 20px;
}


.cm-photo-choice strong {
  color: #104E45;

  font-size: 14px;

  font-weight: 800;
}


.cm-photo-choice span {
  color: #687A7E;

  font-size: 11px;

  line-height: 1.5;
}


/* ==========================================================
   MANUAL ATTRIBUTES
========================================================== */

.cm-manual-attributes {
  margin-top: 6px;
}


.cm-manual-intro {
  margin-bottom: 24px;

  padding: 16px;

  border: 1px solid #D2DED8;

  border-radius: 16px;

  background: #F5F8F3;
}


.cm-manual-intro strong {
  display: block;

  margin-bottom: 4px;

  color: #104E45;

  font-size: 14px;

  font-weight: 800;
}


.cm-manual-intro p {
  margin: 0;

  color: #506267;

  font-size: 12px;

  line-height: 1.55;
}


/* ==========================================================
   PHOTO CHOICE — MOBILE
========================================================== */

@media (max-width: 560px) {

  .cm-photo-choice {
    grid-template-columns: 1fr;
  }


  .cm-photo-choice button {
    min-height: 110px;
  }

}


/* ==========================================================
   REVIEW IMAGE PREVIEW
   STEP 4
========================================================== */

.cm-review-photo-section {
  margin-top: 14px;
}


.cm-review-photo-label {
  display: block;

  margin-bottom: 8px;

  color: #718185;

  font-size: 11px;

  font-weight: 700;
}


.cm-review-photo-card {
  width: 100%;

  max-width: 430px;

  overflow: hidden;

  border: 1px solid #D2DED8;

  border-radius: 18px;

  background: #FFFFFF;

  box-shadow:
    0 6px 18px rgba(16,78,69,.06);
}


.cm-review-photo-image {
  display: block;

  width: 100%;

  height: 240px;

  object-fit: cover;

  object-position: center;

  background: #EDF5E9;
}


.cm-review-photo-info {
  padding:
    12px
    14px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;
}


.cm-review-photo-info strong {
  min-width: 0;

  flex: 1;

  overflow: hidden;

  color: #104E45;

  font-size: 11px;

  font-weight: 800;

  text-overflow: ellipsis;

  white-space: nowrap;
}


.cm-review-photo-info span {
  flex-shrink: 0;

  color: #718185;

  font-size: 10px;
}


.cm-review-no-photo {
  width: 100%;

  max-width: 430px;

  padding: 15px;

  display: flex;

  align-items: center;

  gap: 12px;

  border: 1px solid #D2DED8;

  border-radius: 16px;

  background: #F5F8F3;
}


.cm-review-no-photo-icon {
  width: 42px;

  height: 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 13px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-review-no-photo-icon svg {
  width: 22px;

  height: 22px;
}


.cm-review-no-photo strong {
  display: block;

  margin-bottom: 3px;

  color: #104E45;

  font-size: 11px;

  font-weight: 800;
}


.cm-review-no-photo p {
  margin: 0;

  color: #718185;

  font-size: 10px;

  line-height: 1.45;
}


@media (max-width: 560px) {

  .cm-review-photo-card,
  .cm-review-no-photo {
    max-width: none;
  }


  .cm-review-photo-image {
    height: 200px;
  }


  .cm-review-photo-info {
    align-items: flex-start;

    flex-direction: column;

    gap: 4px;
  }

}


@media (max-width: 380px) {

  .cm-review-photo-image {
    height: 175px;
  }

}

sp_widget.script:
(function() {


    /* ======================================================
       TABLE
    ====================================================== */

    var ITEM_TABLE =
        'x_snc_campusmatch_campusmatch_item';


    /* ======================================================
       LOCATION PICKER
       LOAD ONLY WHEN PAGE FIRST OPENS
    ====================================================== */

    if (!input) {

        data.locationPicker =
            $sp.getWidget(
                'campusmatch_location_picker'
            );

    }


    /* ======================================================
       DEFAULT OUTPUT
    ====================================================== */

    data.success = false;

    data.message = '';

    data.sys_id = '';

    data.number = '';


    /* ======================================================
       CENTRALIZED ACCESS HELPER
    ====================================================== */

    var access =
        new CampusMatchAccess();


    /* ======================================================
       STRING HELPER
    ====================================================== */

    function cleanString(value) {

        if (
            value === null ||
            value === undefined
        ) {

            return '';

        }

        return value
            .toString()
            .trim();

    }


    /* ======================================================
       ISO → CURRENT USER LOCAL VALUE
    ====================================================== */

    function isoToUserLocalInternal(value) {

        var raw =
            cleanString(
                value
            );


        if (!raw) {

            return '';

        }


        try {

            var normalized =
                raw
                    .replace(
                        'T',
                        ' '
                    )
                    .replace(
                        /\.\d+Z$/,
                        ''
                    )
                    .replace(
                        /Z$/,
                        ''
                    );


            var gdt =
                new GlideDateTime();


            gdt.setValue(
                normalized
            );


            return gdt
                .getDisplayValueInternal();

        }
        catch (ex) {

            gs.error(
                'CampusMatch ISO conversion failed for [' +
                raw +
                ']: ' +
                ex.message
            );


            return '';

        }

    }


    /* ======================================================
       EXTRACT USER DATE
    ====================================================== */

    function extractReportedDate(value) {

        var raw =
            cleanString(
                value
            );


        if (!raw) {

            return '';

        }


        if (
            /^\d{4}-\d{2}-\d{2}$/
                .test(
                    raw
                )
        ) {

            return raw;

        }


        if (
            raw.indexOf(
                'T'
            ) >= 0
        ) {

            var localValue =
                isoToUserLocalInternal(
                    raw
                );


            if (!localValue) {

                return '';

            }


            return localValue.substring(
                0,
                10
            );

        }


        if (
            raw.length >= 10
        ) {

            return raw.substring(
                0,
                10
            );

        }


        return '';

    }


    /* ======================================================
       EXTRACT USER TIME
    ====================================================== */

    function extractReportedTime(value) {

        var raw =
            cleanString(
                value
            );


        if (!raw) {

            return '';

        }


        if (
            /^\d{2}:\d{2}$/
                .test(
                    raw
                )
        ) {

            return raw +
                ':00';

        }


        if (
            /^\d{2}:\d{2}:\d{2}$/
                .test(
                    raw
                )
        ) {

            return raw;

        }


        if (
            /^\d{2}:\d{2}:\d{2}\.\d+$/
                .test(
                    raw
                )
        ) {

            return raw.substring(
                0,
                8
            );

        }


        if (
            raw.indexOf(
                'T'
            ) >= 0
        ) {

            var localValue =
                isoToUserLocalInternal(
                    raw
                );


            if (
                !localValue ||
                localValue.length < 19
            ) {

                return '';

            }


            return localValue.substring(
                11,
                19
            );

        }


        if (
            raw.indexOf(
                ' '
            ) >= 0 &&
            raw.length >= 19
        ) {

            return raw.substring(
                11,
                19
            );

        }


        return '';

    }


    /* ======================================================
       BUILD REPORTED DATE/TIME

       FORM VALUE = INDIA STANDARD TIME
       DATABASE VALUE = UTC

       IST = UTC + 05:30
       Therefore subtract 330 minutes.
    ====================================================== */

    function buildReportedDateTime(
        reportedDate,
        reportedTime
    ) {

        var datePart =
            extractReportedDate(
                reportedDate
            );


        if (!datePart) {

            return '';

        }


        var timePart =
            extractReportedTime(
                reportedTime
            );


        if (!timePart) {

            timePart =
                '00:00:00';

        }


        if (
            /^\d{2}:\d{2}$/
                .test(
                    timePart
                )
        ) {

            timePart =
                timePart +
                ':00';

        }


        var userDateTime =
            datePart +
            ' ' +
            timePart;


        try {

            /*
             * ==================================================
             * IMPORTANT
             *
             * The CampusMatch form value is already INDIA
             * LOCAL TIME.
             *
             * Example:
             *
             * 2026-10-02 18:10:00 IST
             *
             * First we tell ServiceNow:
             *
             * "Treat this exact string as UTC."
             *
             * Then we subtract 5 hours 30 minutes.
             *
             * Result:
             *
             * 18:10 - 05:30
             * =
             * 12:40 UTC
             *
             * This avoids Packages.java timezone APIs,
             * which were causing the previous conversion
             * to fail inside the scoped CampusMatch app.
             * ==================================================
             */


            var gdt =
                new GlideDateTime();


            /* ==============================================
               SET THE FORM VALUE AS A UTC BASE VALUE
            ============================================== */

            gdt.setValueUTC(
                userDateTime,
                'yyyy-MM-dd HH:mm:ss'
            );


            /* ==============================================
               IST → UTC

               5 hours 30 minutes
               =
               330 minutes
               =
               19,800,000 milliseconds
            ============================================== */

            gdt.add(
                -19800000
            );


            /* ==============================================
               RETURN DATABASE UTC VALUE
            ============================================== */

            var utcValue =
                gdt.getValue();


            /*
             * DEBUG LOG
             *
             * Example:
             *
             * Input:
             * 2026-10-02 18:10:00
             *
             * Output:
             * 2026-10-02 12:40:00
             */

            gs.info(
                'CampusMatch DEBUG - IST=[' +
                userDateTime +
                '] UTC=[' +
                utcValue +
                ']'
            );


            return utcValue;

        }
        catch (ex) {

            gs.error(
                'CampusMatch Reported Date/Time conversion failed. ' +
                'Input=[' +
                userDateTime +
                '] Error=[' +
                ex.message +
                ']'
            );


            return '';

        }

    }


    /* ======================================================
       CHECK FUTURE REPORTED DATE / TIME
    ====================================================== */

    function isFutureReportedDateTime(
        reportedDateTimeValue
    ) {

        var raw =
            cleanString(
                reportedDateTimeValue
            );


        if (!raw) {

            return false;

        }


        try {

            var selected =
                new GlideDateTime();


            selected.setValue(
                raw
            );


            var now =
                new GlideDateTime();


            return (
                selected.getNumericValue() >
                now.getNumericValue()
            );

        }
        catch (ex) {

            gs.error(
                'CampusMatch future date/time validation failed [' +
                raw +
                ']: ' +
                ex.message
            );


            /*
             * Fail safely.
             * If validation cannot be performed,
             * block the report.
             */

            return true;

        }

    }


    /* ======================================================
       HELPER — FIND VALID FIELD
    ====================================================== */

    function findField(
        gr,
        possibleNames
    ) {

        for (
            var i = 0;
            i < possibleNames.length;
            i++
        ) {

            if (
                gr.isValidField(
                    possibleNames[i]
                )
            ) {

                return possibleNames[i];

            }

        }


        return '';

    }


    /* ======================================================
       CONVERT UPLOADED IMAGE ATTACHMENT
    ====================================================== */

    if (
        input &&
        input.action ===
            'convertImageAttachment'
    ) {

        var itemSysId =
            cleanString(
                input.item_sys_id
            );


        var attachmentSysId =
            cleanString(
                input.attachment_sys_id
            );


        var uploadedFileName =
            cleanString(
                input.file_name
            );


        /* =========================================
           ITEM ID IS ALWAYS REQUIRED
        ========================================== */

        if (!itemSysId) {

            data.success = false;

            data.message =
                'CampusMatch Item information is missing.';

            return;

        }


        /* =========================================
           LOAD CAMPUSMATCH ITEM
        ========================================== */

        var imageItem =
            new GlideRecord(
                ITEM_TABLE
            );


        if (
            !imageItem.get(
                itemSysId
            )
        ) {

            data.success = false;

            data.message =
                'CampusMatch Item could not be found.';

            return;

        }


        /* =========================================
           SECURITY
           OWNER OR ADMIN/STAFF ONLY
        ========================================== */

        if (
            !access.ownsItem(
                imageItem
            ) &&
            !access.isStaff()
        ) {

            data.success = false;

            data.message =
                'You cannot upload an image to this report.';

            return;

        }


        /* =========================================
           GLOBAL ATTACHMENT HELPER
        ========================================== */

        var helper =
            new global
                .CampusMatchAttachmentHelper();


        var conversionResult;


        /* =========================================
           NORMAL CASE
           snAttachmentHandler returned sys_id.
        ========================================== */

        if (attachmentSysId) {

            conversionResult =
                helper.convertToUserImage(
                    attachmentSysId,
                    itemSysId
                );

        }


        /* =========================================
           NORMAL-USER FALLBACK

           Upload succeeded but response did not
           expose attachment sys_id.

           Find attachment using:
           Item + filename.
        ========================================== */

        else {

            if (!uploadedFileName) {

                data.success = false;

                data.message =
                    'Uploaded image information is missing.';

                return;

            }


            conversionResult =
                helper
                    .findAndConvertToUserImage(
                        itemSysId,
                        uploadedFileName
                    );

        }


        /* =========================================
           CONVERSION FAILED
        ========================================== */

        if (
            !conversionResult ||
            !conversionResult.success
        ) {

            data.success = false;

            data.message =
                (
                    conversionResult &&
                    conversionResult.message
                )
                    ?
                    conversionResult.message
                    :
                    'The uploaded image could not be converted.';


            return;

        }


        /*
         * Normal attachment
         *      ↓
         * USER_IMAGE representation
         *      ↓
         * existing attachment Business Rule
         *      ↓
         * AI Ready = true
         *      ↓
         * AI processing
         *      ↓
         * AI Processed = true
         *      ↓
         * Match Orchestrator
         */


        data.success = true;


        data.message =
            'Image attached successfully.';


        data.attachment_sys_id =
            conversionResult
                .attachment_sys_id ||
            attachmentSysId ||
            '';


        return;

    }


    /* ======================================================
       RUN MATCHING FOR NO-IMAGE REPORT
    ====================================================== */

    if (
        input &&
        input.action ===
            'runMatching'
    ) {

        var matchingItemId =
            cleanString(
                input.item_sys_id
            );


        if (!matchingItemId) {

            data.success = false;

            data.message =
                'CampusMatch Item ID is missing.';

            return;

        }


        var matchingItem =
            new GlideRecord(
                ITEM_TABLE
            );


        if (
            !matchingItem.get(
                matchingItemId
            )
        ) {

            data.success = false;

            data.message =
                'CampusMatch Item could not be found.';

            return;

        }


        if (
            !access.ownsItem(
                matchingItem
            ) &&
            !access.isStaff()
        ) {

            data.success = false;

            data.message =
                'You cannot start matching for this report.';

            return;

        }


        try {

            var orchestrator =
                new CampusMatchMatchOrchestrator();


            orchestrator.processItem(
                matchingItem
            );


            data.success = true;


            data.message =
                'Matching completed successfully.';

        }
        catch (ex) {

            data.success = false;


            data.message =
                'The report was created, but matching could not be started.';


            gs.error(
                'CampusMatch matching failed for Item ' +
                matchingItemId +
                ': ' +
                ex.message
            );

        }


        return;

    }


    /* ======================================================
       ONLY RUN CREATE LOGIC WHEN USER SUBMITS
    ====================================================== */

    if (
        !input ||
        input.action !==
            'createReport'
    ) {

        return;

    }


    /* ======================================================
       BASIC VALIDATION
    ====================================================== */

    var reportType =
        cleanString(
            input.report_type
        )
        .toLowerCase();


    var title =
        cleanString(
            input.title
        );


    var category =
        cleanString(
            input.category
        );


    var description =
        cleanString(
            input.description
        );


    /* ======================================================
       PHOTO / MANUAL ATTRIBUTE MODE
       NEW
    ====================================================== */

    var photoMode =
        cleanString(
            input.photo_mode
        )
        .toLowerCase();


    var brand =
        cleanString(
            input.brand
        );


    var color =
        cleanString(
            input.color
        );


    var uniqueFeatures =
        cleanString(
            input.unique_features
        );


    /* ======================================================
       BASIC FIELD VALIDATION
    ====================================================== */

    if (
        reportType !==
            'lost' &&
        reportType !==
            'found'
    ) {

        data.message =
            'Please select Lost or Found.';

        return;

    }


    if (!title) {

        data.message =
            'Title is required.';

        return;

    }


    if (!category) {

        data.message =
            'Category is required.';

        return;

    }


    /* ======================================================
       PHOTO MODE VALIDATION
       NEW
    ====================================================== */

    if (
        photoMode !==
            'yes' &&
        photoMode !==
            'no'
    ) {

        data.message =
            'Please specify whether a photo is available.';

        return;

    }


    /* ======================================================
       NO PHOTO → MANUAL ATTRIBUTES REQUIRED
       NEW

       BRAND = OPTIONAL
       COLOR = REQUIRED
       UNIQUE FEATURES = REQUIRED
    ====================================================== */

    if (
        photoMode ===
            'no'
    ) {

        if (!color) {

            data.message =
                'Color is required when no photo is available.';

            return;

        }


        if (!uniqueFeatures) {

            data.message =
                'Unique features are required when no photo is available.';

            return;

        }

    }


    /* ======================================================
       CREATE ITEM
    ====================================================== */

    var item =
        new GlideRecord(
            ITEM_TABLE
        );


    item.initialize();


    /* ======================================================
       CORE FIELDS
    ====================================================== */

    item.setValue(
        'report_type',
        reportType
    );


    item.setValue(
        'title',
        title
    );


    item.setValue(
        'category',
        category
    );


    item.setValue(
        'description',
        description
    );


    item.setValue(
        'reporter',
        access.getUserId()
    );


    item.setValue(
        'status',
        'active'
    );


    /* ======================================================
       LOCATION
    ====================================================== */

    if (
        input.location_x !==
            undefined &&
        input.location_x !==
            null &&
        input.location_x !==
            ''
    ) {

        item.setValue(
            'location_x',
            input.location_x
        );

    }


    if (
        input.location_y !==
            undefined &&
        input.location_y !==
            null &&
        input.location_y !==
            ''
    ) {

        item.setValue(
            'location_y',
            input.location_y
        );

    }


    if (input.location_zone) {

        item.setValue(
            'location_zone',
            input.location_zone
        );

    }


    /* ======================================================
       REPORTED DATE / TIME
    ====================================================== */


    /* ======================================================
       DATE IS REQUIRED
    ====================================================== */

    if (!input.reported_date) {

        data.message =
            reportType === 'found'
                ? 'Date Found is required.'
                : 'Date Lost is required.';

        return;

    }


    /* ======================================================
       TIME IS REQUIRED
    ====================================================== */

    if (!input.reported_time) {

        data.message =
            'Approximate Time is required.';

        return;

    }


    /* ======================================================
       DEBUG — INPUT VALUES
    ====================================================== */

    gs.info(
        'CampusMatch DEBUG - reported_date=[' +
        input.reported_date +
        '] reported_time=[' +
        input.reported_time +
        ']'
    );


    var reportedDateTimeValue =
        buildReportedDateTime(
            input.reported_date,
            input.reported_time
        );


    if (!reportedDateTimeValue) {

        data.message =
            'The reported date or time could not be processed.';

        return;

    }


    /*
     * SERVER-SIDE FUTURE DATE/TIME PROTECTION
     *
     * Even if somebody bypasses the HTML max
     * restriction, CampusMatch will reject it.
     */

    if (
        isFutureReportedDateTime(
            reportedDateTimeValue
        )
    ) {

        data.message =
            'Future date or time is not allowed. Please select the current date/time or an earlier value.';

        return;

    }


    item.setValue(
        'reported_date_time',
        reportedDateTimeValue
    );


    /* ======================================================
       NO-PHOTO MANUAL VISUAL ATTRIBUTES
       NEW
    ====================================================== */

    if (
        photoMode ===
            'no'
    ) {

        /* ==============================================
           BRAND
           OPTIONAL
        ============================================== */

        if (
            item.isValidField(
                'brand'
            ) &&
            brand
        ) {

            item.setValue(
                'brand',
                brand
            );

        }


        /* ==============================================
           COLOR
        ============================================== */

        if (
            item.isValidField(
                'color'
            )
        ) {

            item.setValue(
                'color',
                color
            );

        }


        /* ==============================================
           UNIQUE FEATURES
        ============================================== */

        if (
            item.isValidField(
                'unique_features'
            )
        ) {

            item.setValue(
                'unique_features',
                uniqueFeatures
            );

        }


        /* ==============================================
           BUILD MANUAL ATTRIBUTE TEXT
        ============================================== */

        var manualAttributeParts =
            [];


        if (brand) {

            manualAttributeParts.push(
                'Brand: ' +
                brand
            );

        }


        if (color) {

            manualAttributeParts.push(
                'Color: ' +
                color
            );

        }


        if (uniqueFeatures) {

            manualAttributeParts.push(
                'Unique features: ' +
                uniqueFeatures
            );

        }


        var manualAttributeText =
            manualAttributeParts.join(
                '. '
            );


        /* ==============================================
           STORE IN AI ATTRIBUTE TEXT

           This lets the existing matching pipeline
           compare manually entered visual information.
        ============================================== */

        if (
            item.isValidField(
                'ai_attribute_text'
            )
        ) {

            item.setValue(
                'ai_attribute_text',
                manualAttributeText
            );

        }

    }


    /* ======================================================
       FOUND-ONLY PRIVATE DETAILS
    ====================================================== */

    if (
        reportType ===
            'found'
    ) {

        var private1 =
            cleanString(
                input.private_1
            );


        var private2 =
            cleanString(
                input.private_2
            );


        var private3 =
            cleanString(
                input.private_3
            );


        if (
            !private1 ||
            !private2
        ) {

            data.message =
                'Please provide the first two private verification details.';

            return;

        }


        var privateField1 =
            findField(
                item,
                [
                    'private_verification_detail_1',
                    'u_private_verification_detail_1',
                    'private_detail_1',
                    'u_private_detail_1',
                    'verification_detail_1',
                    'u_verification_detail_1'
                ]
            );


        var privateField2 =
            findField(
                item,
                [
                    'private_verification_detail_2',
                    'u_private_verification_detail_2',
                    'private_detail_2',
                    'u_private_detail_2',
                    'verification_detail_2',
                    'u_verification_detail_2'
                ]
            );


        var privateField3 =
            findField(
                item,
                [
                    'private_verification_detail_3',
                    'u_private_verification_detail_3',
                    'private_detail_3',
                    'u_private_detail_3',
                    'verification_detail_3',
                    'u_verification_detail_3'
                ]
            );


        if (
            !privateField1 ||
            !privateField2
        ) {

            data.message =
                'Private verification fields could not be found on CampusMatch Item.';

            return;

        }


        item.setValue(
            privateField1,
            private1
        );


        item.setValue(
            privateField2,
            private2
        );


        if (
            privateField3 &&
            private3
        ) {

            item.setValue(
                privateField3,
                private3
            );

        }

    }


    /* ======================================================
       INSERT
    ====================================================== */

    var sysId =
        item.insert();


    if (!sysId) {

        data.message =
            'CampusMatch could not create the report.';

        return;

    }


    /* ======================================================
       RETURN CREATED RECORD
    ====================================================== */

    item.get(
        sysId
    );


    data.success =
        true;


    data.sys_id =
        sysId;


    data.number =
        item.getDisplayValue(
            'number'
        );


    data.message =
        'Report created successfully.';

})();
